def stable_toposort(graph):
    nodes = list(graph.keys())
    node_set = set(nodes)

    # Validate: all dependencies must exist as keys in the graph
    for node, deps in graph.items():
        for dep in deps:
            if dep not in node_set:
                raise ValueError(
                    f"Missing dependency: {dep!r} required by {node!r}"
                )

    # Build unmet-dependency counts and reverse adjacency (dependents)
    unmet = {}
    for node, deps in graph.items():
        unmet[node] = len(deps)

    dependents = {node: [] for node in nodes}
    for node, deps in graph.items():
        for dep in deps:
            dependents[dep].append(node)

    result = []
    processed = set()

    # Repeatedly pick the first ready node in original dict insertion order
    while len(result) < len(nodes):
        found = False
        for node in nodes:
            if node not in processed and unmet[node] == 0:
                processed.add(node)
                result.append(node)
                found = True
                for dependent in dependents[node]:
                    unmet[dependent] -= 1
                break
        if not found:
            remaining = [n for n in nodes if n not in processed]
            raise ValueError(
                f"Cycle detected among nodes: {remaining}"
            )

    return result
```

