def merge_payload_ranges(items):
    for start, end, payload in items:
        if start > end:
            raise ValueError(f"Invalid range: start ({start}) > end ({end})")

    sorted_items = sorted(items, key=lambda x: (x[0], x[1]))

    merged = []

    for start, end, payload in sorted_items:
        to_merge = []
        for i, (ms, me, mp) in enumerate(merged):
            if mp == payload and me + 1 >= start and ms <= end + 1:
                to_merge.append(i)

        if to_merge:
            new_start = min([start] + [merged[i][0] for i in to_merge])
            new_end = max([end] + [merged[i][1] for i in to_merge])
            for i in sorted(to_merge, reverse=True):
                del merged[i]
            merged.append([new_start, new_end, payload])
        else:
            merged.append([start, end, payload])

    merged.sort(key=lambda x: (x[0], x[1]))
    return merged
```

